import torch


def run(grad, self_sizes, dim, index):
    return torch.ops.aten.index_select_backward(
        grad, self_sizes, dim, index
    )


def run_correctness(grad, self_sizes, dim, index):
    ndim = grad.dim()
    d = dim if dim >= 0 else dim + ndim
    out = torch.zeros(
        tuple(self_sizes), dtype=torch.float32, device=grad.device
    )
    out.index_add_(d, index.to(torch.int64), grad.float())
    return out.to(grad.dtype)


def gen_inputs(ctx, device):
    import torch

    self_sizes = ctx["self_sizes"]
    dim = ctx["dim"]
    d = dim if dim >= 0 else dim + len(self_sizes)
    dim_size_out = self_sizes[d]
    grad_shape = ctx["grad__shape"]
    index_len = grad_shape[d]
    index = torch.randint(0, dim_size_out, (index_len,), device=device)
    return {"index": index}
